fn main() {
    let mut rng = ChaCha8Rng::seed_from_u64(42);
    let normal = Normal::new(500.0, 20.0).unwrap();
    let mut a: f64 = 1_000_000.0;
    let mut b: f64 = 0.0;
    let mut bins = [0u64; 40];
    for _ in 0..60 {
        let decay_a = 0.1 * a * 1.0;
        let decay_b = 0.05 * b * 1.0;
        let a_new = a - decay_a;
        let b_new = b + decay_a - decay_b;
        a = a_new;
        b = b_new;
        let detected = (decay_b * 0.1).floor() as u64;
        for _ in 0..detected {
            let e: f64 = normal.sample(&mut rng);
            if (400.0..600.0).contains(&e) {
                bins[((e - 400.0) / 5.0) as usize] += 1;
            }
        }
    }
    let mut out = String::new();
    for (i, c) in bins.iter().enumerate() {
        out.push_str(&format!("{},{}\n", 400 + 5 * i, c));
    }
    std::fs::write("/home/user/spectrum.csv", out).unwrap();
}
EOF
